        black.format_file_contents(src, fast=True, mode=mode)
    except black.NothingChanged:
        pass
    except Exception:
        pass


def main():
    atheris.Setup(sys.argv, TestOneInput)
    atheris.Fuzz()


if __name__ == "__main__":
    main()

